const D = { n:3, scale:1, energy:.6, wind:.4, density:.5, hue:35, speed:1, x:.5, y:.95, seed:0, style:'silhouette', act:'breeze', rim:1 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q=Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q-Math.floor(q); };
const lp=(a,b,t)=>a+(b-a)*t;
const TAU=Math.PI*2;
const W=width, Hh=height, u=Math.min(W,Hh);
const H=((P.hue%360)+360)%360;
const styles=['silhouette','sunset','blueprint','riso','noir'];
const st=styles.includes(P.style)?P.style:'silhouette';
const n=Math.max(1,Math.min(5,Math.round(P.n)));
const dens=Math.max(.2,Math.min(1,P.density));
const nFr=Math.round(lp(6,13,dens));
const spd=P.speed;
const sc=P.scale;

function pal(){
  if(st==='sunset') return {body:[H,58,10], rim:[33,92,100], glow:[24,88,94], sun:[30,80,100], sky:1, riso:0};
  if(st==='blueprint') return {body:null, rim:[198,72,98], glow:[200,60,42], sun:[200,40,70], sky:0, riso:0};
  if(st==='riso') return {body:[184,72,82], rim:[9,84,96], glow:[184,42,32], sun:[9,60,80], sky:0, riso:1};
  if(st==='noir') return {body:[0,0,6], rim:[0,0,97], glow:[0,0,62], sun:[0,0,90], sky:0, riso:0};
  return {body:[H,26,9], rim:[H,62,58], glow:[H,46,28], sun:[H,50,55], sky:0, riso:0};
}
const C=pal();

// act shaping (multi-minute weather)
let actWind=1, actGust=1;
if(P.act==='gale'){ actWind=1.9; actGust=1.7; }
else if(P.act==='still'){ actWind=.35; actGust=.4; }

// wind: continuous real-time floor (K.t) + audio/beat gust on top
const w1=Math.sin(K.t*0.55*spd)*0.6 + Math.sin(K.t*1.31*spd+1.2)*0.4;
S.gust = (S.gust==null?0:S.gust)*0.9 + (((A.lowmid||0)*0.8)+K.swell*0.4)*0.1;
const baseSway = P.energy*actWind*(w1*0.55) + P.energy*actGust*(S.gust*0.7);
const secDrift = 0.6 + 0.7*K.intensity;   // 30s-5min arc: fronds open/close with section energy

// build cache (seed/size/count/frond-count deterministic)
if(S.key!==W+'x'+Hh+'|'+P.seed+'|'+n+'|'+nFr){
  S.palms=[];
  for(let i=0;i<n;i++){
    const t=n===1?0.5:i/(n-1);
    const bxf=lp(0.16,0.84,t)+(fr(i*7+1)-0.5)*0.10;
    const hFrac=lp(0.46,0.70,fr(i*3))*(0.85+0.3*fr(i*5));
    const lean=(fr(i*9)-0.5)*0.9;
    const fn=Math.max(5,nFr+Math.round((fr(i*11)-0.5)*3));
    const fronds=[];
    for(let j=0;j<fn;j++){
      const ftr=fn===1?0.5:j/(fn-1);
      const ang=lp(-Math.PI*0.99,-Math.PI*0.01,ftr);
      const len=lp(0.52,0.98,fr(i*13+j*3));
      const droop=lp(0.55,1.25,fr(i*17+j*3));
      const ph=fr(i*19+j*3)*TAU;
      fronds.push({ang,len,droop,ph});
    }
    S.palms.push({bxf,hFrac,lean,fronds,ph:fr(i*23)*TAU});
  }
  S.key=W+'x'+Hh+'|'+P.seed+'|'+n+'|'+nFr;
}

// ── drifting sun / glow behind (continuous bright-region motion → carries gate) ──
const gx=W*(0.30+0.40*(0.5+0.5*Math.sin(K.t*0.09*spd)));
const gy=P.y*Hh - u*0.06;
const flick=0.85+0.15*Math.sin(K.t*1.7)+ (A.rms||0)*0.6;
blendMode(ADD); noStroke();
if(st!=='blueprint'){
  for(let i=0;i<6;i++){ const r=u*(1.05-i*0.14); fill(C.glow[0],C.glow[1],C.glow[2], (7-i)*flick); ellipse(gx,gy,r,r); }
  if(st==='sunset'||st==='noir'){ fill(C.sun[0],C.sun[1],C.sun[2], 70*flick); ellipse(gx,gy,u*0.30,u*0.30); }
} else {
  // schematic sun ring
  blendMode(BLEND); noFill(); stroke(C.sun[0],C.sun[1],C.sun[2],55); strokeWeight(1.5);
  ellipse(gx,gy,u*0.34,u*0.34);
  for(let a=0;a<12;a++){ const an=a/12*TAU; stroke(C.sun[0],C.sun[1],C.sun[2],28); line(gx+Math.cos(an)*u*0.19,gy+Math.sin(an)*u*0.19,gx+Math.cos(an)*u*0.23,gy+Math.sin(an)*u*0.23); }
  blendMode(ADD);
}
blendMode(BLEND);

// ── draw a frond spine as marching curve, then render per style ──
function frondPts(ox,oy,frd,pm){
  const N=7, flen=frd.len*u*sc*0.6, dl=flen/N;
  const windDir = baseSway>=0?1:-1;
  let px=ox, py=oy, ang=frd.ang;
  const pts=[{x:px,y:py,a:ang}];
  for(let s=1;s<=N;s++){
    const f=s/N;
    const bend = baseSway*f*f*0.9*(0.6+0.4*Math.sin(K.t*1.9*spd+frd.ph));
    ang = frd.ang + frd.droop*f*secDrift*0.95 + bend;
    px+=Math.cos(ang)*dl; py+=Math.sin(ang)*dl;
    pts.push({x:px,y:py,a:ang});
  }
  return pts;
}
function blade(pts, colF, wB){
  noStroke(); fill(colF[0],colF[1],colF[2], colF[3]==null?100:colF[3]);
  beginShape();
  for(let s=0;s<pts.length;s++){ const f=s/(pts.length-1); const w=wB*Math.pow(1-f,0.7); const nx=Math.cos(pts[s].a+Math.PI/2), ny=Math.sin(pts[s].a+Math.PI/2); vertex(pts[s].x+nx*w,pts[s].y+ny*w); }
  for(let s=pts.length-1;s>=0;s--){ const f=s/(pts.length-1); const w=wB*Math.pow(1-f,0.7); const nx=Math.cos(pts[s].a+Math.PI/2), ny=Math.sin(pts[s].a+Math.PI/2); vertex(pts[s].x-nx*w,pts[s].y-ny*w); }
  endShape(CLOSE);
}

// ── trunk (tapered curved strip) ──
function trunk(bx,by,cx,cy,lean){
  const mx=lp(bx,cx,0.5)+lean*u*0.05*sc, my=lp(by,cy,0.5);
  const N=6, wB=u*0.026*sc, wT=u*0.011*sc;
  const q=(p0,p1,p2,t)=>{const it=1-t; return it*it*p0+2*it*t*p1+t*t*p2;};
  const pts=[];
  for(let s=0;s<=N;s++){ const t=s/N; const x=q(bx,mx,cx,t), y=q(by,my,cy,t); const dx=q(bx,mx,cx,t+0.01)-x, dy=q(by,my,cy,t+0.01)-y; const l=Math.hypot(dx,dy)||1; pts.push({x,y,nx:-dy/l,ny:dx/l,w:lp(wB,wT,t)}); }
  if(st==='blueprint'){ noFill(); stroke(C.rim[0],C.rim[1],C.rim[2],90); strokeWeight(1.4); beginShape(); for(const p of pts) vertex(p.x+p.nx*p.w,p.y+p.ny*p.w); endShape(); beginShape(); for(const p of pts) vertex(p.x-p.nx*p.w,p.y-p.ny*p.w); endShape(); return; }
  noStroke(); fill(C.body[0],C.body[1],C.body[2]);
  beginShape(); for(const p of pts) vertex(p.x+p.nx*p.w,p.y+p.ny*p.w); for(let s=pts.length-1;s>=0;s--){const p=pts[s]; vertex(p.x-p.nx*p.w,p.y-p.ny*p.w);} endShape(CLOSE);
  // trunk banding texture
  stroke(C.body[0],C.body[1],Math.max(0,C.body[2]-4),60); strokeWeight(1);
  for(let s=1;s<N;s++){ const p=pts[s]; line(p.x-p.nx*p.w,p.y-p.ny*p.w,p.x+p.nx*p.w,p.y+p.ny*p.w); }
  noStroke();
}

for(let pi=0;pi<S.palms.length;pi++){
  const pm=S.palms[pi];
  const bx=pm.bxf*W+(P.x-0.5)*W;
  const by=P.y*Hh;
  const tl=pm.hFrac*u*sc;
  const cx=bx + (pm.lean*0.10 + baseSway*0.06*Math.cos(pm.ph))*u*sc;
  const cy=by - tl;
  trunk(bx,by,cx,cy,pm.lean);
  const wB=u*0.019*sc;
  // coconuts
  if(st!=='blueprint'){ noStroke(); fill(C.body[0],Math.min(100,C.body[1]+10),Math.max(0,C.body[2]+3)); for(let k=0;k<3;k++){ const an=-Math.PI/2+(k-1)*0.5; ellipse(cx+Math.cos(an)*u*0.02*sc, cy+Math.sin(an)*u*0.012*sc+u*0.01*sc, u*0.022*sc,u*0.022*sc); } }
  for(const frd of pm.fronds){
    const pts=frondPts(cx,cy,frd,pm);
    if(st==='blueprint'){
