      for(let s=1;s<pts.length-1;s+=1){ const p=pts[s]; const f=s/(pts.length-1); const w=wB*Math.pow(1-f,0.7)*2.4; const nx=Math.cos(p.a+Math.PI/2), ny=Math.sin(p.a+Math.PI/2); line(p.x,p.y,p.x+nx*w,p.y+ny*w); line(p.x,p.y,p.x-nx*w,p.y-ny*w); }
    } else if(st==='riso'){
      const d=u*0.006;
      blendMode(MULTIPLY);
      blade(pts.map(p=>({x:p.x-d,y:p.y-d,a:p.a})),[C.body[0],C.body[1],C.body[2],78],wB);
