      blendMode(BLEND);
    } else {
      blade(pts,C.body,wB);
      // rim light on the sun-facing edge
      if(C.sky || st==='noir' || st==='silhouette'){ const side=(cx<gx)?1:-1; noFill(); stroke(C.rim[0],C.rim[1],C.rim[2],(st==='sunset'?70:48)*P.rim); strokeWeight(Math.max(1,u*0.0016*sc)); beginShape(); for(const p of pts){ const f=(pts.indexOf(p))/(pts.length-1); const w=wB*Math.pow(1-f,0.7)*side; const nx=Math.cos(p.a+Math.PI/2), ny=Math.sin(p.a+Math.PI/2); vertex(p.x+nx*w,p.y+ny*w); } endShape(); noStroke(); }
    }
  }
}

